class Solution {
public:
    long long maximumSumOfHeights(vector<int>& maxHeights) {
        int n = maxHeights.size();
        vector<long long> left(n, 0), right(n, 0);
        vector<int> stack = {-1};
        long long curr = 0;
        for (int i = 0; i < n; i++) {
            int h = maxHeights[i];
            while (stack.size() > 1 && maxHeights[stack.back()] > h) {
                int idx = stack.back();
                stack.pop_back();
                curr -= 1LL * maxHeights[idx] * (idx - stack.back());
            }
            curr += 1LL * h * (i - stack.back());
            stack.push_back(i);
            left[i] = curr;
        }
        stack = {n};
        curr = 0;
        for (int i = n - 1; i >= 0; i--) {
            int h = maxHeights[i];
            while (stack.size() > 1 && maxHeights[stack.back()] > h) {
                int idx = stack.back();
                stack.pop_back();
                curr -= 1LL * maxHeights[idx] * (stack.back() - idx);
            }
            curr += 1LL * h * (stack.back() - i);
            stack.push_back(i);
            right[i] = curr;
        }
        long long ans = 0;
        for (int i = 0; i < n; i++) ans = max(ans, left[i] + right[i] - maxHeights[i]);
        return ans;
    }
};

class Solution {
    public long maximumSumOfHeights(List<Integer> maxHeights) {
        int n = maxHeights.size();
        long[] left = new long[n];
        long[] right = new long[n];
        int[] stack = new int[n + 2];
        int top = 0;
        stack[top] = -1;
        long curr = 0;
        for (int i = 0; i < n; i++) {
            int h = maxHeights.get(i);
            while (top > 0 && maxHeights.get(stack[top]) > h) {
                int idx = stack[top--];
                curr -= (long) maxHeights.get(idx) * (idx - stack[top]);
            }
            curr += (long) h * (i - stack[top]);
            stack[++top] = i;
            left[i] = curr;
        }
        top = 0;
        stack[top] = n;
        curr = 0;
        for (int i = n - 1; i >= 0; i--) {
            int h = maxHeights.get(i);
            while (top > 0 && maxHeights.get(stack[top]) > h) {
                int idx = stack[top--];
                curr -= (long) maxHeights.get(idx) * (stack[top] - idx);
            }
            curr += (long) h * (stack[top] - i);
            stack[++top] = i;
            right[i] = curr;
        }
        long ans = 0;
        for (int i = 0; i < n; i++) ans = Math.max(ans, left[i] + right[i] - maxHeights.get(i));
        return ans;
    }
}

/**
 * @param {number[]} maxHeights
 * @return {number}
 */
var maximumSumOfHeights = function(maxHeights) {
    const n = maxHeights.length;
    const left = new BigInt64Array(n);
    const right = new BigInt64Array(n);
    const stack = [-1];
    let curr = 0n;
    for (let i = 0; i < n; i++) {
        const h = BigInt(maxHeights[i]);
        while (stack.length > 1 && maxHeights[stack[stack.length - 1]] > maxHeights[i]) {
            const idx = stack.pop();
            curr -= BigInt(maxHeights[idx]) * BigInt(idx - stack[stack.length - 1]);
        }
        curr += h * BigInt(i - stack[stack.length - 1]);
        stack.push(i);
        left[i] = curr;
    }
    stack.length = 0;
    stack.push(n);
    curr = 0n;
    for (let i = n - 1; i >= 0; i--) {
        const h = BigInt(maxHeights[i]);
        while (stack.length > 1 && maxHeights[stack[stack.length - 1]] > maxHeights[i]) {
            const idx = stack.pop();
            curr -= BigInt(maxHeights[idx]) * BigInt(stack[stack.length - 1] - idx);
        }
        curr += h * BigInt(stack[stack.length - 1] - i);
        stack.push(i);
        right[i] = curr;
    }
    let ans = 0n;
    for (let i = 0; i < n; i++) {
        const total = left[i] + right[i] - BigInt(maxHeights[i]);
        if (total > ans) ans = total;
    }
    return Number(ans);
};
